  fib: (n: number, ack: (result: number) => void) => void;
}
interface ClientToServerEvents {
  fib: (n: number) => Promise<number>;      // the ack, typed
}
const socket: Socket<ServerToClientEvents, ClientToServerEvents> = io();
const result = await socket.timeout(5_000).emitWithAck('fib', 10); // number

// server: the ack callback IS the return address
socket.on('fib', (n, ack) => ack(fib(n)));

